public static void main(String [] args)
{
     class solve
    {
        long bridge,connection;
        solve(Scanner in)
        {
            this.bridge=in.nextLong();
            this.connection=in.nextLong();
            long []diff =new long[(int)bridge+2];
            long last=-1,ans=0;

            for(long i=0;i<connection;i++)
            {
                long now=in.nextLong();
                long mini=last,maxi=now;
                if(last!=-1)
                {
                    if(last>now)
                    {
                        mini=now;
                        maxi=last;
                    }
                    long cost1=maxi-mini;
                    long cost2=mini+bridge-maxi;
                    ans+=Math.min(cost1,cost2);
                    long seperate=Math.abs(cost1-cost2);
                    if(cost1>cost2)
                    {
                        diff[1]+=seperate;
                        diff[(int)mini+1]-=seperate;
                        diff[(int)maxi+1]+=seperate; // Adjusting the indices to correctly reflect the changes in the cost when a bridge is closed.
                    }
                    else
                    {
                        diff[(int)mini+1]+=seperate;
                        diff[(int)maxi+1]-=seperate;
                    }
                }
                last=now;
            }
            long total=Long.MAX_VALUE; // Use Long.MAX_VALUE to ensure we find the minimum correctly.
            for(long i=1;i<=bridge;i++)
            {
                diff[(int)i]+=diff[(int)i-1];
                total=Math.min(total,diff[(int)i]);
            }
            total = Math.min(total, diff[1] + diff[(int)bridge]); // Ensure we consider the circular nature of the bridges.
            System.out.println(ans+total);
        }
    }
    Scanner in=new Scanner(System.in);
    solve n=new solve(in);
    // close(in);
}

